import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    for record in reader:
        if record:
            records.append(record)

    if not records:
        return {"columns": [], "rows": []}

    columns = list(records[0])
    rows = records[1:]

    width = max([len(columns)] + [len(row) for row in rows])
    while len(columns) < width:
        name = f"column_{len(columns) + 1}"
        while name in columns:
            name += "_"
        columns.append(name)

    normalized_rows = [
        row + [""] * (width - len(row))
        for row in rows
    ]

    return {"columns": columns, "rows": normalized_rows}
